from itertools import permutations, product

# Each piece maps local coordinates (relative to its 7x7 core) to output color.
pieces = {
    2: {(r,c):2 for r in range(7) for c in range(7) if (r,c) not in {(0,3),(3,0),(3,1),(3,2)}},
    3: {(r,c):3 for r in range(7) for c in range(7) if not (r in (4,5,6) and c==3)},
    7: {(r,c):7 for r in range(7) for c in range(7) if not (r==3 and c in (0,1))},
    8: {(r,c):8 for r in range(7) for c in range(7)},
}
pieces[3].update({(3,c):3 for c in (-3,-2,-1)})
pieces[7].update({(r,3):7 for r in (-3,-2,-1)})
pieces[8].update({(3,7):8,(7,3):8,(8,3):8})
pieces[7][(6,6)] = 5
print({k:len(v) for k,v in pieces.items()},sum(len(v) for v in pieces.values()))

def tf_coord(r,c,rot=0, refl=False):
    if refl: c=6-c
    for _ in range(rot):
        r,c=c,6-r
    return r,c

def transform_piece(p,rot,refl):
    return {tf_coord(r,c,rot,refl):v for (r,c),v in p.items()}
transforms={k:[(rot,refl,transform_piece(p,rot,refl)) for refl in (False,True) for rot in range(4)] for k,p in pieces.items()}
quads=[(0,0),(0,7),(7,0),(7,7)]
sols=[]
for qassign in permutations(quads):
    # qassign aligns piece order [2,3,7,8]
    for orientations in product(range(8),repeat=4):
        cells={}
        good=True
        for k,q,oi in zip((2,3,7,8),qassign,orientations):
            tr=transforms[k][oi][2]
            for (r,c),v in tr.items():
                pos=(q[0]+r,q[1]+c)
                if not (0<=pos[0]<14 and 0<=pos[1]<14) or pos in cells:
                    good=False;break
                cells[pos]=v
            if not good: break
        if good and len(cells)==196:
            sols.append((qassign,orientations,cells))
print('solutions',len(sols))

for i,(qa,oris,cells) in enumerate(sols):
    p5=next(pos for pos,v in cells.items() if v==5)
    print(i, 'quads',dict(zip((2,3,7,8),qa)), 'ori',dict(zip((2,3,7,8),[(transforms[k][o][0],transforms[k][o][1]) for k,o in zip((2,3,7,8),oris)])), 'marker',p5)

def make_piece_demo():
    P={}
    P[9]={(r,c):9 for r in range(3) for c in range(3) if (r,c)!=(0,1)}
    P[9][(1,3)]=9
    P[7]={}
    m7=[[7,7,5],[0,7,7],[7,0,7]]
    for r in range(3):
        for c in range(3):
            if m7[r][c]: P[7][(r,c)]=m7[r][c]
    P[4]={(r,c):4 for r in range(3) for c in range(3)}
    P[4].update({(-2,1):4,(-1,1):4,(1,-1):4})
    P[3]={(r,c):3 for r in range(3) for c in range(3) if not (r==1 and c==1)}
    # Wait source 3 core r17-19 c17-19 = rows 111,001,111, one missing at (1,0),(1,1), not one only.
    P[3]={(r,c):3 for r in range(3) for c in range(3) if not (r==1 and c in (0,1))}
    P[3][(-1,1)]=3
    return P
D=make_piece_demo()
print({k:len(v) for k,v in D.items()})

def trans_piece_side(p,n,rot,refl):
    def f(r,c):
        if refl: c=n-1-c
        for _ in range(rot): r,c=c,n-1-r
        return r,c
    return {f(r,c):v for (r,c),v in p.items()}

def find_solutions(P,n):
    keys=tuple(P)
    T={k:[(rot,refl,trans_piece_side(P[k],n,rot,refl)) for refl in (False,True) for rot in range(4)] for k in keys}
    qs=[(0,0),(0,n),(n,0),(n,n)]
    out=[]
    for qa in permutations(qs):
      for os in product(range(8),repeat=4):
        cells={}; ok=True
        for k,q,oi in zip(keys,qa,os):
          for (r,c),v in T[k][oi][2].items():
            pos=(q[0]+r,q[1]+c)
            if not (0<=pos[0]<2*n and 0<=pos[1]<2*n) or pos in cells:
                ok=False;break
            cells[pos]=v
          if not ok:break
        if ok and len(cells)==(2*n)**2: out.append((qa,os,cells))
    return T,out
Td,dsols=find_solutions(D,3)
print('count',len(dsols))
expected=[
[5,7,7,9,9,9],
[7,7,9,9,9,9],
[7,4,7,9,3,9],
[4,4,4,3,3,3],
[4,4,4,4,4,3],
[4,4,4,3,3,3],]
for i,(qa,os,cells) in enumerate(dsols):
    grid=[[cells[(r,c)] for c in range(6)] for r in range(6)]
    if grid==expected:
        print('expected solution index',i,'qa',dict(zip(D.keys(),qa)), 'ori',dict(zip(D.keys(),[(Td[k][o][0],Td[k][o][1]) for k,o in zip(D.keys(),os)])))

